<?php
namespace App\Services\Selection; use App\Models\{CricketMatch,MatchSquad,MatchSquadPlayer,Player,SelectionDecision,Squad,Team}; use Illuminate\Support\Facades\DB;
class MatchSquadService { public function __construct(private readonly SelectionEligibilityService $eligibility,private readonly SelectionContextService $context,private readonly SelectionAuditService $audit){} public function save(CricketMatch $match,Team $team,?Squad $squad,array $players,int $actor):MatchSquad{$this->eligibility->assertMatchTeam($match,$team);return DB::transaction(function()use($match,$team,$squad,$players,$actor){$ms=MatchSquad::query()->updateOrCreate(['match_id'=>$match->id,'team_id'=>$team->id],['organization_id'=>$match->organization_id,'squad_id'=>$squad?->id,'status'=>'Draft','created_by'=>$actor]);$ids=[];foreach($players as $item){$id=(int)$item['player_id'];$ids[]=$id;$this->eligibility->assertPlayerInTournamentSquad($squad,$id);$p=Player::query()->findOrFail($id);$a=$this->eligibility->assertAvailability($p,$match,(bool)($item['override']??false),$item['override_reason']??null);MatchSquadPlayer::query()->updateOrCreate(['match_squad_id'=>$ms->id,'player_id'=>$id],['selection_status'=>'Selected','override_used'=>$a['override_used'],'override_reason'=>$item['override_reason']??null]);SelectionDecision::query()->create(['organization_id'=>$match->organization_id,'match_id'=>$match->id,'team_id'=>$team->id,'player_id'=>$id,'decision_type'=>'MatchSquad','decision'=>'Selected','reason'=>$item['reason']??null,'context'=>$this->context->forPlayer($p,$match),'override_used'=>$a['override_used'],'created_by'=>$actor]);}$ms->players()->whereNotIn('player_id',$ids?:[-1])->delete();$this->audit->record('match_squad.updated',$actor,['match_squad_id'=>$ms->id,'player_ids'=>$ids]);return $ms->fresh(['players.player']);});} }
